const productsMainHtml = "<section class=\"hero\">\n      <div class=\"shell\">\n        <article class=\"hero-card\">\n          <div class=\"hero-grid\">\n            <div class=\"hero-copy\">\n              <span class=\"eyebrow\">Product Selection</span>\n              <h1>Flooring products for Sydney homes and apartments</h1>\n              <p>Compare hybrid, laminate and engineered timber flooring, then choose a product direction before starting your quote.</p>\n              <div class=\"hero-actions\" style=\"margin-top: 24px;\">\n                <a class=\"button\" href=\"quote.html?from=product#quoteForm\">Start quote</a>\n                <a class=\"button-secondary\" href=\"floorplan.html\">Upload Floor Plan</a>\n                <a class=\"button-secondary\" href=\"quote-review.html\">Check existing quote</a>\n              </div>\n              <div class=\"pill-row\" style=\"margin-top: 24px;\">\n                <span class=\"pill\">1 Choose category</span>\n                <span class=\"pill\">2 Select range</span>\n                <span class=\"pill\">3 Continue to quote</span>\n              </div>\n            </div>\n              <div class=\"stat-stack\">\n                <div class=\"stat-card\">\n                  <strong>Fastest path into a quote</strong>\n                  Pick a flooring type, choose a product direction, then continue with that context carried into the quote.\n                </div>\n              <div class=\"stat-card\">\n                <strong>Sydney quote support</strong>\n                Product, area and key details are reviewed before the final quote.\n              </div>\n              <div class=\"stat-card\">\n                <strong>Best use</strong>\n                Use this page to shortlist a range before estimating or checking a written quote.\n              </div>\n            </div>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"shell\">\n        <article class=\"section-card\">\n          <span class=\"eyebrow\">Product Guidance</span>\n          <h2 style=\"margin-top: 18px;\">Choose your flooring type</h2>\n          <p>Start with the flooring category that fits the property, room use and quote path. You can still confirm the final range later.</p>\n          <div class=\"catalogue-category-cards\" id=\"catalogueCategoryCards\"></div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"shell\">\n        <article class=\"section-card\">\n          <span class=\"eyebrow\">Compare Categories</span>\n          <h2 style=\"margin-top: 18px;\">Compare flooring types before browsing</h2>\n          <div class=\"grid-3\" style=\"margin-top: 24px;\">\n            <article class=\"decision-guide-card\">\n              <h3>Hybrid flooring</h3>\n              <p><strong>Best for:</strong> practical family homes, apartments, water-resistant needs and low maintenance.</p>\n              <p><strong>Watch-outs:</strong> subfloor and acoustic layer still need review. Product thickness and range can affect the quote.</p>\n              <a class=\"button-secondary\" href=\"quote.html?from=product&category=hybrid#quoteForm\" data-track-cta=\"products_hybrid_quote_click\">Start quote with hybrid</a>\n            </article>\n            <article class=\"decision-guide-card\">\n              <h3>Laminate flooring</h3>\n              <p><strong>Best for:</strong> cost-conscious renovations, rental upgrades and dry internal spaces.</p>\n              <p><strong>Watch-outs:</strong> not the first choice for wet-prone areas. Product quality and underlay still matter.</p>\n              <a class=\"button-secondary\" href=\"quote.html?from=product&category=laminate#quoteForm\" data-track-cta=\"products_laminate_quote_click\">Start quote with laminate</a>\n            </article>\n            <article class=\"decision-guide-card\">\n              <h3>Engineered timber</h3>\n              <p><strong>Best for:</strong> premium timber feel, higher-spec renovations and feature areas.</p>\n              <p><strong>Watch-outs:</strong> range, colour and installation method can affect the quote more. Herringbone or feature patterns need review.</p>\n              <a class=\"button-secondary\" href=\"quote.html?from=product&category=engineered#quoteForm\" data-track-cta=\"products_engineered_quote_click\">Start quote with timber</a>\n            </article>\n          </div>\n          <div class=\"hero-actions\" style=\"margin-top: 24px;\">\n            <a class=\"button\" href=\"quote.html?from=product&product_status=undecided#quoteForm\" data-track-cta=\"products_start_undecided_click\">Not sure yet? Start undecided</a>\n            <a class=\"button-secondary\" href=\"quote-review.html\" data-track-cta=\"products_quote_review_click\">Already have a quote? Review it</a>\n            <a class=\"button-secondary\" href=\"floorplan.html\" data-track-cta=\"products_floorplan_click\">Need area? Use floor plan</a>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"shell\">\n        <article class=\"section-card\">\n          <span class=\"eyebrow\">Scope clarity</span>\n          <h2 style=\"margin-top: 18px;\">Clear scope before the job is booked</h2>\n          <p>Operon helps Sydney customers choose a product direction and confirm the main inclusions before installation is booked.</p>\n          <div class=\"trust-card-grid\">\n            <article class=\"trust-card\">\n              <h3>Product and area checked</h3>\n              <p>Flooring type, selected range and measured area are reviewed before final confirmation.</p>\n            </article>\n            <article class=\"trust-card\">\n              <h3>Removal, trims and stairs clarified</h3>\n              <p>Removal, disposal, scotia, skirting, trims and stair details are checked so the written inclusions are easier to compare.</p>\n            </article>\n            <article class=\"trust-card\">\n              <h3>Project details reviewed</h3>\n              <p>Apartment requirements, preparation notes and other project details are confirmed where relevant.</p>\n            </article>\n            <article class=\"trust-card\">\n              <h3>Written assumptions</h3>\n              <p>The aim is to make the product direction and main inclusions clear before the job is booked.</p>\n            </article>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\" id=\"ranges\">\n      <div class=\"shell\">\n        <article class=\"section-card\">\n          <span class=\"eyebrow\">Live Catalogue</span>\n          <h2 style=\"margin-top: 18px;\">Browse the live catalogue</h2>\n          <p>Filter by category, range, colour or thickness. Choose a range if you know it, or continue to the quote undecided.</p>\n          <p class=\"catalogue-guidance-note\">Choosing a product category or range is enough to start most quotes. Final colour can often be confirmed later, with feature timber patterns reviewed before confirmation.</p>\n\n          <div class=\"catalogue-toolbar\">\n            <div class=\"catalogue-category-row\" id=\"catalogueCategoryRow\"></div>\n            <div class=\"catalogue-search-form\" role=\"search\" aria-label=\"Search flooring ranges\">\n              <div class=\"catalogue-filter catalogue-search-field\">\n                <label for=\"catalogueSearchInput\">Search ranges</label>\n                <input id=\"catalogueSearchInput\" type=\"search\" autocomplete=\"off\" placeholder=\"Search by range, brand, colour or thickness\">\n              </div>\n              <button class=\"button catalogue-search-button\" id=\"catalogueSearchButton\" type=\"button\">Search</button>\n            </div>\n            <div class=\"catalogue-toolbar-grid\">\n              <div class=\"catalogue-filter\">\n                <label for=\"catalogueBrandFilter\">Brand</label>\n                <select id=\"catalogueBrandFilter\"></select>\n              </div>\n              <div class=\"catalogue-filter\">\n                <label for=\"catalogueColourFilter\">Colour</label>\n                <select id=\"catalogueColourFilter\"></select>\n              </div>\n              <div class=\"catalogue-filter\">\n                <label for=\"catalogueThicknessFilter\">Thickness</label>\n                <select id=\"catalogueThicknessFilter\"></select>\n              </div>\n            </div>\n            <div class=\"catalogue-toolbar-actions\">\n              <button class=\"button-quiet\" id=\"catalogueResetFilters\" type=\"button\">Clear filters</button>\n            </div>\n          </div>\n\n          <div class=\"catalogue-selection-banner\" id=\"catalogueSelectionBanner\">\n            <strong id=\"catalogueSelectionTitle\">No product direction selected yet</strong>\n            <p id=\"catalogueSelectionText\">Choose a range if you know it, or start with a category if you are still comparing products.</p>\n            <p class=\"catalogue-selection-meta\" id=\"catalogueSelectionMeta\">Product direction can be attached to the quote without locking the final colour too early.</p>\n            <div class=\"catalogue-selection-actions\">\n              <a class=\"button\" id=\"catalogueContinueQuote\" href=\"quote.html?from=product#quoteForm\">Continue to quote</a>\n              <button class=\"button-secondary\" id=\"catalogueClearSelection\" type=\"button\">Clear selection</button>\n            </div>\n            <div class=\"catalogue-context-links\" id=\"catalogueContextLinks\"></div>\n          </div>\n\n          <div class=\"catalogue-results-head\">\n            <div>\n              <h2 style=\"margin: 0;\">Available flooring products</h2>\n              <p id=\"catalogueResultsSummary\">Loading flooring products...</p>\n            </div>\n            <a class=\"button-quiet\" id=\"catalogueSkipToQuote\" href=\"quote.html?from=product#quoteForm\">Start quote undecided</a>\n          </div>\n\n          <div class=\"catalogue-grid\" id=\"catalogueProductsGrid\"></div>\n          <div class=\"catalogue-empty\" id=\"catalogueEmptyState\" hidden>No products match the current filters. Adjust the filters or switch category.</div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"shell\">\n        <article class=\"section-card\">\n          <span class=\"eyebrow\">Not Sure Yet?</span>\n          <h2 style=\"margin-top: 18px;\">Not sure what to choose yet?</h2>\n          <p>If you are still comparing products, start the quote with the closest category or leave the final range undecided. Operon can review product fit alongside area and the main inclusions.</p>\n          <div class=\"hero-actions\" style=\"margin-top: 24px;\">\n            <a class=\"button\" id=\"startQuoteUndecidedButton\" href=\"quote.html#quoteForm\">Start quote undecided</a>\n            <a class=\"button-secondary\" href=\"blog/\">Read comparison guides</a>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"section\">\n      <div class=\"shell\">\n        <article class=\"section-card\">\n          <h2>Choose the product here, structure the estimate in the quote</h2>\n          <p>Shortlist the range here. Confirm scope in the quote.</p>\n          <div class=\"faq-grid\" style=\"margin-top: 22px;\">\n            <details>\n              <summary>Why choose a range before quoting?</summary>\n              <p>Choosing a range first gives the quote a clearer product direction and avoids comparing a job with no real product basis behind it. Hybrid and laminate can usually start from the range alone, while engineered timber often benefits from careful colour, pattern and installation-method confirmation before final approval.</p>\n            </details>\n            <details>\n              <summary>Can colour be confirmed later?</summary>\n              <p>Yes, in many cases colour can be confirmed later once the broader range and quote path are clear. For engineered timber, colour and grade are best reviewed before final confirmation.</p>\n            </details>\n            <details>\n              <summary>What should I check before selecting a product?</summary>\n              <p>Check the flooring type, thickness, colour direction, maintenance expectations and whether the product suits the room. If you are still unsure, shortlist the likely range now and use the quote flow to confirm the final product during review.</p>\n            </details>\n            <details>\n              <summary>What moves from product choice into the quote?</summary>\n              <p>The product page helps you shortlist the flooring direction. The quote then reviews measured area, supply or installation path, main inclusions and final confirmation items. That keeps product browsing simple while still giving the estimate enough detail to be useful.</p>\n            </details>\n          </div>\n        </article>\n      </div>\n    </section>";

